def _has_code(func: Optional[Callable[..., Any]], code: CodeType) ->Optional[
    Callable[..., Any]]:
    if func is None:
        return None
    func_code = getattr(func, '__code__', None)
    if func_code is code:
        return func
    return None

def get_func(frame: FrameType) ->Optional[Callable[..., Any]]:
    code = frame.f_code
    if code.co_name is None:
        return None

    candidate = None

    for name in ('self', 'cls'):
        if name in frame.f_locals:
            obj = frame.f_locals[name]
            candidate = get_func_in_mro(obj, code)
            if candidate is not None:
                return candidate

    for val in get_locals_from_previous_frames(frame):
        candidate = get_func_in_mro(val, code)
        if candidate is not None:
            return candidate
        if isinstance(val, type):
            for cls in val.__mro__:
                candidate = get_func_in_mro(cls, code)
                if candidate is not None:
                    return candidate

    for val in frame.f_globals.values():
        if callable(val):
            candidate = _has_code(val, code)
            if candidate is not None:
                return candidate
        if isinstance(val, type):
            candidate = get_func_in_mro(val, code)
            if candidate is not None:
                return candidate

    return None
